<script setup lang="ts">import{computed}from'vue';interface Props{modelValue?:number;totalPages:number;label?:string;maxVisible?:number};const props=withDefaults(defineProps<Props>(),{modelValue:1,label:'Pagination',maxVisible:7});const emit=defineEmits<{'update:modelValue':[page:number];change:[page:number]}>();const pages=computed(()=>{const max=Math.max(1,props.totalPages);const count=Math.min(props.maxVisible,max);let start=Math.max(1,props.modelValue-Math.floor(count/2));start=Math.min(start,max-count+1);return Array.from({length:count},(_,i)=>start+i)});function go(page:number){const next=Math.min(props.totalPages,Math.max(1,page));if(next===props.modelValue)return;emit('update:modelValue',next);emit('change',next)}</script>
<template><nav class="uv-pagination" :aria-label="label"><button type="button" :disabled="modelValue<=1" aria-label="Previous page" @click="go(modelValue-1)">‹</button><button v-for="page in pages" :key="page" type="button" :class="{'active':page===modelValue}" :aria-current="page===modelValue?'page':undefined" :aria-label="`Page ${page}`" @click="go(page)">{{page}}</button><button type="button" :disabled="modelValue>=totalPages" aria-label="Next page" @click="go(modelValue+1)">›</button></nav></template>
<style>.uv-pagination{display:flex;align-items:center;gap:.35rem;font-family:var(--uv-font-sans,system-ui,sans-serif)}.uv-pagination button{display:grid;place-items:center;min-width:2.3rem;height:2.3rem;border:1px solid var(--uv-color-border,#dbe3ef);border-radius:.5rem;background:var(--uv-color-surface,#fff);color:var(--uv-color-text,#0f172a)}.uv-pagination button:hover:not(:disabled){border-color:var(--uv-color-primary,#2563eb);color:var(--uv-color-primary,#2563eb)}.uv-pagination button.active{border-color:var(--uv-color-primary,#2563eb);background:var(--uv-color-primary,#2563eb);color:var(--uv-color-primary-contrast,#fff)}.uv-pagination button:focus-visible{outline:0;box-shadow:var(--uv-focus-ring)}.uv-pagination button:disabled{opacity:.45}</style>
